import os, csv, json, hashlib

FILES = [
    # F1–F4
    "f1_per_agent.csv",
    "f2_novelty_timeline.csv",
    "f3_timesliced_combined.csv",
    "f3_timesliced_sources.csv",
    "f4_rolling_combined.csv",
    "f4_rolling_sources.csv",
    # v2.4
    "joint_metrics_v2_4_per_lineage.csv",
    "joint_metrics_v2_4_per_agent.csv",
    # v2.5
    "joint_metrics_v2_5_adjacency.csv",
    "joint_metrics_v2_5_per_lineage_rolling.csv",
]

BASE = "storage/shared/agency_lab/analyses/csv"
REPORT = "storage/shared/agency_lab/analyses/axiom_report_v1_2b_interactions_official_v2_1.txt"

def md5_of_file(path):
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

def summarize_csv(path):
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.reader(f)
        rows = list(reader)
    if not rows:
        return {"rows": 0, "cols": 0, "header": [], "sample": []}
    return {"rows": len(rows) - 1, "cols": len(rows[0]), "header": rows[0], "sample": rows[1:3]}

def main():
    os.makedirs(BASE, exist_ok=True)
    manifest = {"csv": {}, "report": {}}

    for fname in FILES:
        fpath = os.path.join(BASE, fname)
        if os.path.exists(fpath):
            entry = summarize_csv(fpath)
            entry["md5"] = md5_of_file(fpath)
            manifest["csv"][fname] = entry
        else:
            manifest["csv"][fname] = {"missing": True}

    if os.path.exists(REPORT):
        manifest["report"] = {
            "path": REPORT,
            "md5": md5_of_file(REPORT),
            "size_bytes": os.path.getsize(REPORT),
        }
    else:
        manifest["report"] = {"missing": True, "path": REPORT}

    out_json = os.path.join(BASE, "qc_manifest.json")
    out_txt = os.path.join(BASE, "qc_manifest.txt")

    with open(out_json, "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2)

    lines = ["QC MANIFEST"]
    rep = manifest.get("report", {})
    if "md5" in rep:
        lines.append(f"REPORT OK md5={rep['md5']} size={rep['size_bytes']}")
    else:
        lines.append("REPORT MISSING")
    for fname, info in manifest["csv"].items():
        if "missing" in info:
            lines.append(f"{fname}: MISSING")
        else:
            lines.append(f"{fname}: rows={info['rows']} cols={info['cols']} md5={info['md5']}")

    with open(out_txt, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")

    print("QC_DONE", out_json, out_txt)
    return 0

if __name__ == "__main__":
    import sys
    try:
        sys.exit(main())
    except Exception as e:
        print("ERROR", str(e))
        sys.exit(1)
